import type { ElementType } from 'react';
import './glitch-split-text.css';

export interface GlitchSplitTextProps {
  text: string;
  /** Element to render, for example "h2". */
  as?: ElementType;
  /** Change this value to play the glitch again. */
  playKey?: number | string;
  className?: string;
}

/**
 * Two colored copies slip sideways and settle back into one heading. The
 * copies are decorative; only the real text is exposed, and the main text
 * never disappears, so the effect does not flash.
 */
export function GlitchSplitText({
  text,
  as: Tag = 'h2',
  playKey = 0,
  className = '',
}: GlitchSplitTextProps) {
  return (
    <Tag className={`mg-glitch ${className}`}>
      <span className='mg-glitch__text'>{text}</span>
      <span
        key={`a-${playKey}`}
        className='mg-glitch__layer mg-glitch__layer--a'
        aria-hidden='true'
      >
        {text}
      </span>
      <span
        key={`b-${playKey}`}
        className='mg-glitch__layer mg-glitch__layer--b'
        aria-hidden='true'
      >
        {text}
      </span>
    </Tag>
  );
}

.mg-glitch {
  position: relative;
  display: inline-block;
  margin: 0;
}

.mg-glitch__text {
  position: relative;
  z-index: 1;
}

.mg-glitch__layer {
  position: absolute;
  inset: 0;
  opacity: 0;
  pointer-events: none;
  mix-blend-mode: multiply;
}

.mg-glitch__layer--a {
  color: var(--mg-accent-text, #648aff);
  animation: mg-glitch-a 720ms cubic-bezier(0.3, 0.7, 0.3, 1) both;
}

.mg-glitch__layer--b {
  color: var(--mg-accent-text, #8aa8ff);
  animation: mg-glitch-b 720ms cubic-bezier(0.3, 0.7, 0.3, 1) both;
}

/* Smooth slides, not flicker: each layer eases out over ~0.7s. */
@keyframes mg-glitch-a {
  0% {
    opacity: 0.9;
    transform: translate(-6px, 0);
    clip-path: inset(0 0 55% 0);
  }
  40% {
    opacity: 0.8;
    transform: translate(4px, 0);
    clip-path: inset(30% 0 20% 0);
  }
  100% {
    opacity: 0;
    transform: none;
    clip-path: inset(0);
  }
}

@keyframes mg-glitch-b {
  0% {
    opacity: 0.9;
    transform: translate(6px, 0);
    clip-path: inset(45% 0 0 0);
  }
  40% {
    opacity: 0.8;
    transform: translate(-4px, 0);
    clip-path: inset(10% 0 50% 0);
  }
  100% {
    opacity: 0;
    transform: none;
    clip-path: inset(0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .mg-glitch__layer {
    display: none;
  }
}
